const checkDomRemoval = function (mutations) {
  const focusedNode = state.mostRecentlyFocusedNode;
  if (!focusedNode) return;

  const isFocusedNodeRemoved = mutations.some(function (mutation) {
    const removedNodes = Array.from(mutation.removedNodes);
    return removedNodes.some(function (node) {
      return node === focusedNode || node.contains(focusedNode);
    });
  });

  // Also check if focused node is no longer in the document
  const isFocusedNodeDetached = !doc.contains(focusedNode);

  // If the currently focused is removed then browsers will move focus to the
  // <body> element. If this happens, try to move focus back into the trap.
  if (isFocusedNodeRemoved || isFocusedNodeDetached) {
    tryFocus(getInitialFocusNode());
  }
};
